/// Models for Phase 5 (Timers & Guest Mode).
///
/// Ported from openGym mobile.js lines 111-121 (buildReminderNotifications).
library;

import 'package:equatable/equatable.dart';

import '../js_codec.dart';

/// One-off scheduled reminder notification generated by [ReminderJs.buildReminderNotifications].
final class ReminderNotification extends Equatable {
  const ReminderNotification({
    required this.id,
    required this.title,
    required this.body,
    required this.at,
    required this.allowWhileIdle,
  });

  factory ReminderNotification.fromJson(
    Map<String, Object?> json, [
    String path = 'reminderNotification',
  ]) {
    final int id = jsInt(json['id'], '$path.id');
    final String title = jsString(json['title'], '$path.title');
    final String body = jsString(json['body'], '$path.body');

    final Map<String, Object?> schedule = jsMap(json['schedule'], '$path.schedule');
    final Object? atRaw = schedule['at'];
    final DateTime at;
    if (atRaw is String) {
      at = DateTime.parse(atRaw).toUtc();
    } else if (atRaw is int) {
      at = DateTime.fromMillisecondsSinceEpoch(atRaw, isUtc: true);
    } else {
      at = DateTime.parse(atRaw.toString()).toUtc();
    }

    final bool allowWhileIdle = schedule['allowWhileIdle'] == true;

    return ReminderNotification(
      id: id,
      title: title,
      body: body,
      at: at,
      allowWhileIdle: allowWhileIdle,
    );
  }

  final int id;
  final String title;
  final String body;
  final DateTime at;
  final bool allowWhileIdle;

  Map<String, Object?> toJson() => <String, Object?>{
        'id': id,
        'title': title,
        'body': body,
        'schedule': <String, Object?>{
          'at': at.toIso8601String(),
          'allowWhileIdle': allowWhileIdle,
        },
      };

  @override
  List<Object?> get props => <Object?>[id, title, body, at, allowWhileIdle];
}
